"""Published Lab 5 behavioral checks. Students run but do not edit this file."""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


TOOL_ROOT = Path(__file__).resolve().parents[1]
SCRIPT = TOOL_ROOT / "inventory.py"


def run_cli(*arguments: str, cwd: Path | None = None) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), *arguments],
        cwd=cwd or TOOL_ROOT,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )


class Lab5PublishedTests(unittest.TestCase):
    def setUp(self) -> None:
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)

    def test_directory_argument_is_used_from_another_working_directory(self) -> None:
        requested = self.root / "requested"
        requested.mkdir()
        (requested / "alpha.txt").write_text("alpha\n", encoding="utf-8")
        elsewhere = self.root / "elsewhere"
        elsewhere.mkdir()
        (elsewhere / "wrong.log").write_text("wrong\n", encoding="utf-8")

        result = run_cli(str(requested), cwd=elsewhere)

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("alpha.txt", result.stdout)
        self.assertNotIn("wrong.log", result.stdout)

    def test_extensionless_file_has_an_empty_extension(self) -> None:
        (self.root / "README").write_text("read\n", encoding="utf-8")

        result = run_cli(str(self.root), cwd=self.root)

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("README\t5\t", result.stdout.splitlines())

    def test_metacharacter_filename_is_plain_data(self) -> None:
        (self.root / "odd;still-data.txt").write_text("safe\n", encoding="utf-8")

        result = run_cli(str(self.root), cwd=self.root)

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("odd;still-data.txt", result.stdout)

    def test_extension_filter_selects_exact_suffix(self) -> None:
        (self.root / "one.txt").write_text("one\n", encoding="utf-8")
        (self.root / "two.log").write_text("two\n", encoding="utf-8")

        result = run_cli(str(self.root), "--ext", ".txt", cwd=self.root)

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("one.txt", result.stdout)
        self.assertNotIn("two.log", result.stdout)

    def test_json_output_is_machine_readable(self) -> None:
        (self.root / "one.txt").write_text("one\n", encoding="utf-8")

        result = run_cli(str(self.root), "--format", "json", cwd=self.root)

        self.assertEqual(result.returncode, 0, result.stderr)
        records = json.loads(result.stdout)
        self.assertEqual(records, [{"extension": "txt", "name": "one.txt", "size": 4}])

    def test_output_option_writes_selected_format(self) -> None:
        source = self.root / "source"
        source.mkdir()
        (source / "one.txt").write_text("one\n", encoding="utf-8")
        generated = self.root / "generated"
        generated.mkdir()
        destination = generated / "report.json"

        result = run_cli(
            str(source),
            "--format",
            "json",
            "--output",
            str(destination),
            cwd=self.root,
        )

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "")
        self.assertEqual(json.loads(destination.read_text(encoding="utf-8"))[0]["name"], "one.txt")

    def test_missing_directory_returns_a_useful_nonzero_error(self) -> None:
        missing = self.root / "does-not-exist"

        result = run_cli(str(missing), cwd=self.root)

        self.assertNotEqual(result.returncode, 0)
        self.assertIn("does-not-exist", result.stderr)


if __name__ == "__main__":
    unittest.main()
